window.VO = [{"id":"n01","text":"You can save the last doctor on Earth, or the last engineer. Not both.","at":0.24,"t0":0.12,"t1":4.25},{"id":"n02","text":"Your parents have been asking you this for years, and now you've got five seconds.","at":9.74,"t0":4.87,"t1":9.15},{"id":"n03","text":"Doctor, or engineer?","at":18.7,"t0":9.35,"t1":10.655},{"id":"m01","text":"Amma! Open his!","at":21.87,"t0":10.935,"t1":12.27},{"id":"r01","text":"Amma! Open hers!","at":24.94,"t0":12.47,"t1":13.96},{"id":"n04a","text":"Stop.","at":29.36,"t0":14.68,"t1":15.33},{"id":"n04b","text":"That isn't their mother they're shouting for.","at":31.66,"t0":15.83,"t1":17.845},{"id":"n04c","text":"It's you.","at":36.45,"t0":18.225,"t1":18.905},{"id":"n05","text":"You're the ship they're drowning in, and the last thousand people alive call you Amma.","at":38.65,"t0":19.325,"t1":23.675},{"id":"n07","text":"Ten seconds as their mother, and you're still picking by degree.","at":47.99,"t0":23.995,"t1":27.285},{"id":"n06","text":"You've got power for one door, no time for another, and everyone watching this gets a vote.","at":55.41,"t0":27.705,"t1":32.46},{"id":"n10","text":"Open hers, and the only man who can run you drowns, and a fifteen-year-old has forty days to learn how, or you all sink.","at":65.56,"t0":32.78,"t1":39.98},{"id":"n08","text":"But Meera and Ravi are married, and you gave the bride away yourself.","at":80.56,"t0":40.28,"t1":43.975},{"id":"n09","text":"And she's carrying the only baby since the world ended.","at":89.95,"t0":44.975,"t1":47.94},{"id":"n11","text":"Open his, and you're safe, with no doctor, no baby, and he spends the rest of his life fixing you.","at":96.88,"t0":48.44,"t1":54.055},{"id":"n12","text":"So, Amma. Meera, or Ravi?","at":109.31,"t0":54.655,"t1":56.55}];
